 * @param {string} jogo - Nome do jogo (ou 'all').
 * @param {object} jogos - Objeto contendo todos os dados dos jogos.
 * @returns {string} A resposta formatada.
 */
function getEstatisticas(jogo, jogos) {
    const header = "🍀 *PORCENTAGENS E ESTATÍSTICAS* 💰\n\n";

    if (jogo === 'all') {
        let resposta = header;
        Object.keys(jogos).forEach(nome => {
            const valores = atualizarValores(jogos[nome]);
            resposta += formatarEstatistica(nome, valores);
        });
        return resposta + "Observação: As porcentagens podem conter alguma divergência...";
    }

    const jogoData = jogos[jogo];
    if (!jogoData) return `❌ Jogo "${jogo}" não encontrado.`;

    const valores = atualizarValores(jogoData);
    return header + formatarEstatistica(jogo, valores) + "Observação: As porcentagens podem conter alguma divergência...";
}


// --- 3. FLUXO DE EXECUÇÃO (Inicialização e Teste) ---

/**
