            // Garante que as chaves existam
            if (!data.casamentos || !data.namoros) {
                fs.writeFileSync(CASAMENTO_JSON_PATH, JSON.stringify({ casamentos: [], namoros: [] }, null, 2));
            }
        } catch (error) {
            console.error(`Erro ao ler ou parsear ${CASAMENTO_JSON_PATH}:`, error.message);
        }
    }

